    public BigDecimal dueTotalBetween(String sheetId, LocalDate from, LocalDate to) {
        List<Rate> sheetRates = rates.findBySheetId(sheetId);
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        Map<Long, Person> personOf = new LinkedHashMap<>();
        people.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> personOf.put(p.getId(), p));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
        for (Claim claim : sheetClaims) {
            Person person = personOf.get(claim.getPersonId());
            if (person == null || !person.counts(claim.getStatus()) || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                continue;
            }
            BigDecimal due = dueOf(claim, ratesOf(sheetRates, person.gradeOn(claim.getDate())), sheet, sheetClaims);
            if (due != null) {
                total = total.add(due);
            }
        }
        return total;
    }

    /**
     * Record, once the change commits, how the sheet's figures moved since {@code before}: a ROLLUP line
     * for each person whose figures changed (one who did not exist before counting as changed), then a
     * TOTALS line if the sheet's totals changed. Nothing is recorded when no figure moved.
     */
    public void recordChanges(String sheetId, String user, Figures before) {
        Figures after = of(sheetId);
        after.people().forEach((id, figures) -> {
            PersonFigures was = before.people().get(id);
            if (was == null || !was.claimed().equals(figures.claimed()) || !was.dueTotal().equals(figures.dueTotal())) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + figures.name()
                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal());
            }
        });
        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal());
        }
    }

    /** The rates of one grade among a sheet's. */
    private static List<Rate> ratesOf(List<Rate> sheetRates, String grade) {
        return sheetRates.stream().filter(r -> r.getGrade().equals(grade)).toList();
    }

    /** A claim's due: its settled figure, else its stated one, else its amount at the rate in force on its date of
     *  its person's grade in force on that date, rounded as the claim rounds (by the sheet's policy date), raised to the sheet's floor unless it is a correction; an overdue claim's late charge is added on top of the figure. */
    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates, Sheet sheet, List<Claim> sheetClaims) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        BigDecimal floor = sheet == null ? null : sheet.getFloor();
        RoundingMode rounding = sheet == null ? RoundingMode.HALF_EVEN
                : sheet.roundingFor(ClaimService.roundingDate(claim, sheetClaims));
        BigDecimal figure = claim.getStatedDue() != null ? claim.getStatedDue()
                : Rate.inForceOn(gradeRates, claim.getDate())
                        .map(rate -> ClaimService.liveFigure(claim, rate.getRate(), floor, rounding))
                        .orElse(null);
        return figure == null || sheet == null ? figure : figure.add(ClaimService.lateCharge(claim, figure, sheet));
    }
}

    /** What a person's statements come to: how many, and the last one's due-total and date. */
    public record Summary(long personId, int count, String dueTotal, LocalDate takenOn) {
    }

    /** A statement just taken: the person's summary and their claims, newest first, as it left them. */
    public record Taken(Summary summary, List<Claim> claims) {
    }

    private final StatementRepository statements;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateRepository rates;
    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final Audit audit;
    private final Rollup rollup;

    public StatementService(StatementRepository statements, ClaimRepository claims, PersonRepository people,
            RateRepository rates, SheetService sheets, SheetRepository sheetStore, Audit audit, Rollup rollup) {
        this.statements = statements;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** The summary of each person on the sheet who has had a statement taken. */
    @Transactional(readOnly = true)
    public List<Summary> list(String sheetId) {
        Map<Long, Summary> byPerson = new LinkedHashMap<>();
        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
            Summary before = byPerson.get(s.getPersonId());
            byPerson.put(s.getPersonId(),
                    new Summary(s.getPersonId(), before == null ? 1 : before.count() + 1, s.getDueTotal(), s.getTakenOn()));
        }
        return List.copyOf(byPerson.values());
    }

    /**
     * Take a statement of a person: record their due-total now (with the late charges their overdue claims have gained), bind each of their claims that counts
     * to the figure it has now (its settled figure, else the figure it is bound to, else its amount at
     * its grade's rate in force on its date) and leave the rest unbound. A late charge is never bound: it keeps
     * following the sheet's today. The sheet is locked first, so
     * a statement is not taken while a claim on it changes.
     */
    @Transactional
    public Taken take(String sheetId, String user, long personId) {
        sheets.load(sheetId, user);
        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
        LocalDate today = sheet.getToday();
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
        Rollup.Figures before = rollup.of(sheetId);
        List<Rate> sheetRates = rates.findBySheetId(sheetId);
        Set<String> grades = new HashSet<>(Set.of(person.gradeOn(today)));
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);

        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean anyFixed = false;
        int counted = 0;
        for (Claim claim : theirs) {
            if (!person.counts(claim.getStatus())) {
                claim.unbind();
                continue;
            }
            BigDecimal fixed = claim.getSettledDue() != null ? claim.getSettledDue() : claim.getStatedDue();
            BigDecimal figure = fixed != null ? fixed
                    : Rate.inForceOn(ratesOf(sheetRates, person.gradeOn(claim.getDate())), claim.getDate())
                            .map(rate -> ClaimService.liveFigure(claim, rate.getRate(), sheet.getFloor(),
                                    sheet.roundingFor(ClaimService.roundingDate(claim, theirs))))
                            .orElse(null);
            anyFixed |= fixed != null;
            grades.add(person.gradeOn(claim.getDate()));
            total = figure == null ? total : total.add(figure).add(ClaimService.lateCharge(claim, figure, sheet));
            claim.bind(figure);
            counted++;
        }
        // As on screen: with no rate in force today for their grade on the sheet's today, nor for the grade any
        // of their claims that count is at, and no fixed figure, the person has no due-total.
        boolean anyRate = grades.stream().anyMatch(g -> Rate.inForceOn(ratesOf(sheetRates, g), today).isPresent());
        String dueTotal = !anyRate && !anyFixed ? "n/a" : total.toPlainString();
        claims.saveAllAndFlush(theirs);
        statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, today));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + dueTotal + " claims=" + counted);
        rollup.recordChanges(sheetId, user, before);
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        return new Taken(new Summary(personId, taken.size(), dueTotal, today), theirs);
    }

    private static List<Rate> ratesOf(List<Rate> sheetRates, String grade) {
        return sheetRates.stream().filter(r -> r.getGrade().equals(grade)).toList();
    }
}

    public boolean isHeld() {
        return held;
    }

    public void setHeld(boolean held) {
        this.held = held;
    }

    /** Whether a claim of this person in {@code status} counts in the live totals: while held, only SETTLED ones do. */
    public boolean counts(ClaimStatus status) {
        return held ? status == ClaimStatus.SETTLED : status.counts();
    }

    /** Whether a claim dated {@code date} is refused: one dated after the retirement date. */
    public boolean refusesClaimOn(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }
}

