export class PersonClaims {
  private readonly sheets = inject(Sheets);
  private readonly session = inject(Session);
  private readonly api = inject(Claims);

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  /** This person's claims, newest first. */
  readonly claims = input.required<ClaimView[]>();
  /** The rates of each grade, in the order they take effect. */
  readonly ratesByGrade = input.required<ReadonlyMap<Grade, readonly RateView[]>>();
  /** This person's grades: a claim is at the one in force on its date. */
  readonly grades = input.required<Pick<PersonView, 'grade' | 'grades'>>();
  /** The sheet's periods, by from-date. */
  readonly periods = input.required<readonly PeriodView[]>();
  /** Whether the person is on hold: their OPEN claims then count in no total. */
  readonly held = input(false);
  /** The ids of the claims selected for a bulk action. */
  readonly selected = input<ReadonlySet<number>>(new Set());
  readonly saved = output<ClaimView>();
  readonly selectToggled = output<{ id: number; selected: boolean }>();

  protected readonly claimed = computed(() => money(this.claims().filter(countsWhile(this.held())).reduce((sum, c) => sum + cents(c.amount), 0)));
  protected readonly editingId = signal<number | null>(null);
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  /** The error of the last action taken on a claim's row, until the next action on that row. */
  protected readonly claimError = signal<{ id: number; message: string } | null>(null);

  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    date: new FormControl('', { nonNullable: true }),
    note: new FormControl('', { nonNullable: true }),
    corrects: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  protected dueOf(c: ClaimView): string {
    const rates = this.ratesByGrade().get(gradeOn(this.grades(), c.date)) ?? NO_RATES;
    const due = claimDueCents(c, rates, this.sheets.current() ?? DEFAULT_DUE_TERMS, roundingDate(c, this.claims()));
    return due === null ? NOT_AVAILABLE : money(due);
  }

  protected dueByOf(c: ClaimView): string {
    return dueBy(c, this.sheets.current()?.terms ?? DEFAULT_TERMS);
  }

  protected overdueOf(c: ClaimView): boolean {
    const sheet = this.sheets.current();
    return sheet !== null && isOverdue(c, sheet.terms, sheet.today);
  }

  protected periodOf(c: ClaimView): string {
    return periodOn(this.periods(), c.date)?.name ?? '';
  }

  protected changeStatus(c: ClaimView, status: ClaimStatus): void {
    this.claimError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.api.changeStatus(sheet.id, c.id, status).subscribe({
      next: (saved) => this.saved.emit(saved),
      error: (err: unknown) => this.claimError.set({
        id: c.id,
        message: err instanceof HttpErrorResponse && err.status === 403
          ? c.openedBy === this.session.user()
            ? 'You opened this claim, so someone else must settle it.'
            : 'Its due is above the clerk limit, so a steward must settle it.'
          : err instanceof HttpErrorResponse && err.status === 423
            ? 'This claim is dated inside a closed period.'
            : `A ${c.status} claim cannot become ${status}.`,
      }),
    });
  }

  protected fieldId(field: string): string {
    return `claim-form-${field}-${this.personId()}`;
  }

  protected edit(c: ClaimView): void {
    this.claimError.set(null);
    // Only a draft can be edited; an open claim is changed by voiding it and adding a new one.
    if (c.status !== 'DRAFT') {
      this.claimError.set({ id: c.id, message: `A ${c.status} claim cannot be edited. Void it and add a new one.` });
      return;
    }
    this.editingId.set(c.id);
    this.form.setValue({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '' },
      { emitEvent: false });
    this.error.set(null);
  }

  protected reset(): void {
    this.editingId.set(null);
    this.form.reset({ amount: '', date: '', note: '', corrects: '' }, { emitEvent: false });
    this.error.set(null);
  }

  protected submit(): void {
    // A second submit before the first has answered is ignored, so it stores one record.
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const value = this.form.getRawValue();
    const amount = value.amount.trim();
    if (!CLAIM_AMOUNT_PATTERN.test(amount)) {
      this.error.set('Type an amount with up to two decimals; a negative one is a correction.');
      return;
    }
    // A negative amount is a correction: it must name the number of a settled claim of this person.
    const correction = amount.startsWith('-');
    const corrects = value.corrects.trim();
    if (correction && !/^\S{1,120}$/.test(corrects)) {
      this.error.set('A negative amount is a correction: type the number of the settled claim it corrects.');
      return;
    }
    if (!correction && corrects !== '') {
      this.error.set('Only a negative amount (a correction) names a claim it corrects.');
      return;
    }
    const date = value.date.trim();
    if (date !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.error.set('Choose a date for the claim, or leave it blank for today.');
      return;
    }
    const claim = { amount, date: date === '' ? null : date, note: value.note, corrects: correction ? corrects : null };
    const id = this.editingId();
    this.saving.set(true);
    const request = id === null ? this.api.add(sheet.id, this.personId(), claim) : this.api.update(sheet.id, id, claim);
    request.subscribe({
      next: (saved) => {
        this.saving.set(false);
        this.saved.emit(saved);
        this.reset();
      },
      error: (err: unknown) => {
        this.saving.set(false);
        this.error.set(
          err instanceof HttpErrorResponse && err.status === 423
            ? 'That claim is dated inside a closed period.'
            : err instanceof HttpErrorResponse && err.status === 422
              ? 'That claim is dated after the person retired.'
            : correction && err instanceof HttpErrorResponse && err.status === 400
              ? `Claim No. ${corrects} is not a settled claim of ${this.personName()}, so this cannot correct it.`
            : id !== null && err instanceof HttpErrorResponse && err.status === 409
              ? 'Only a draft claim can be edited. Void it and add a new one.'
              : id === null ? 'Could not add that claim.' : 'Could not save that claim.',
        );
      },
    });
  }
}
/** The sheet's settings a claim's due depends on: its floor, its policy date and, for the late charge, its
 *  terms, today and late percent. */
export type DueTerms = Pick<SheetView, 'floor' | 'terms' | 'today' | 'latePct' | 'policyDate'>;

/** Whether a claim whose figures round by this date (yyyy-mm-dd) rounds half up: it is before the sheet's policy
 *  date (its today when it has none); on or after it, it rounds half to even. */
export function roundsHalfUp(date: string, sheet: DueTerms): boolean {
  return date < (sheet.policyDate ?? sheet.today);
}

/** The late charge an OPEN claim has gained on its figure (in whole cents) by the sheet's today: the
 *  late percent of the figure for every full 30 days past the day it is due by, rounded as the claim rounds.
 *  A correction (a negative amount) gains none. */
export function lateChargeCents(
  c: { amount: string; date: string; status: ClaimStatus },
  figureCents: number,
  sheet: DueTerms,
): number {
  if (cents(c.amount) < 0 || !isOverdue(c, sheet.terms, sheet.today)) return 0;
  const days = (Date.parse(sheet.today) - Date.parse(dueBy(c, sheet.terms))) / 86_400_000;
  const periods = Math.floor(days / 30);
  if (periods <= 0) return 0;
  return dueCents(figureCents * periods, sheet.latePct, roundsHalfUp(c.date, sheet));
}

/** A claim's due in whole cents: the figure fixed when it was settled, else the figure its person's
 *  last statement bound it to, else its amount at its grade's rate in force on its date raised to the
 *  sheet's floor (a correction is not), with any late charge added on top of it; null when it has none. Its live
 *  figure rounds by `roundsOn`: its date, or for a correction the date of the claim it corrects. */
export function claimDueCents(
  c: { amount: string; date: string; status: ClaimStatus; settledDue: string | null; statedDue: string | null },
  gradeRates: readonly RateView[],
  sheet: DueTerms,
  roundsOn: string,
): number | null {
  if (c.settledDue !== null) return cents(c.settledDue);
  let figure: number;
  if (c.statedDue !== null) {
    figure = cents(c.statedDue);
  } else {
    const rate = rateOn(gradeRates, c.date);
    if (rate === undefined) return null;
    const due = dueCents(cents(c.amount), rate, roundsHalfUp(roundsOn, sheet));
    figure = due < 0 ? due : Math.max(due, cents(sheet.floor));
  }
  return figure + lateChargeCents(c, figure, sheet);
}


// The rates set for each grade on the active sheet, by from-date; a grade with none has no rate.
@Injectable({ providedIn: 'root' })
export class Rates {
  private readonly http = inject(HttpClient);
  private readonly sheets = inject(Sheets);
  private readonly list = signal<RateView[]>([]);
  /** The active sheet's rates of each grade, in the order they take effect. */
  readonly ratesByGrade = computed(() => {
    const byGrade = new Map<Grade, RateView[]>();
    for (const r of [...this.list()].sort(byFrom)) byGrade.set(r.grade, [...(byGrade.get(r.grade) ?? []), r]);
    return byGrade;
  });
  /** The rate of each grade in force on the active sheet's today; a grade with none is missing. */
  readonly byGrade = computed(() => {
    const today = this.sheets.current()?.today ?? '';
    const current = new Map<Grade, string>();
    for (const [grade, rates] of this.ratesByGrade()) {
      const rate = rateOn(rates, today);
      if (rate !== undefined) current.set(grade, rate);
    }
    return current;
  });

  /** Re-read a sheet's rates from the store; null clears them. */
  load(sheetId: string | null): Observable<RateView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<RateView[]>(this.base(sheetId)).pipe(tap((rates) => this.list.set(rates)));
  }

  /** Set a grade's rate from a date (null: from the beginning of time), replacing the one it had from that date. */
  set(sheetId: string, grade: Grade, rate: string, from: string | null): Observable<RateView> {
    return this.http
      .put<RateView>(`${this.base(sheetId)}/${grade}`, { rate, from })
      .pipe(
        tap((saved) =>
          this.list.update((list) => [...list.filter((r) => r.grade !== saved.grade || r.from !== saved.from), saved]),
        ),
      );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }
}

