cd /home/daniel/ui-work/runs/202610271-as/sandbox/officehq-angular-spring/src/main/frontend/src/app/features/settings && python3 - <<'EOF'
import re
p='settings.ts'; s=open(p).read()
for ctl in ['clerkLimit','floor','terms','latePct','policyDate','periodNumberingFrom']:
    a=f'formControlName="{ctl}"'
    assert s.count(a)==1
    s=s.replace(a, a+f' (focus)="lastFocused = \'{ctl}\'"')
a="""  protected readonly settingsForm = new FormGroup({"""
s=s.replace(a,"""  /** The setting field last focused: with no setting changed, it is the one saved as it is. */
  protected lastFocused: SettingField = 'clerkLimit';

"""+a)
a="""    // Only the settings changed in the form are saved; with none changed, the clerk limit is saved as it is.
    const saveFloor = floor.dirty;
    const saveTerms = terms.dirty;
    const saveLatePct = latePct.dirty;
    const savePolicyDate = policyDate.dirty;
    const savePeriodNumberingFrom = periodNumberingFrom.dirty;
    const saveLimit = clerkLimit.dirty || (!saveFloor && !saveTerms && !saveLatePct && !savePolicyDate && !savePeriodNumberingFrom);"""
b="""    // Only the settings changed in the form are saved; with none changed, the field last focused (else the clerk
    // limit) is saved as it is.
    const unchanged = !this.settingsForm.dirty;
    const saves_ = (field: SettingField) => this.settingsForm.controls[field].dirty || (unchanged && this.lastFocused === field);
    const saveFloor = saves_('floor');
    const saveTerms = saves_('terms');
    const saveLatePct = saves_('latePct');
    const savePolicyDate = saves_('policyDate');
    const savePeriodNumberingFrom = saves_('periodNumberingFrom');
    const saveLimit = saves_('clerkLimit');"""
assert a in s; s=s.replace(a,b)
s=s.replace('saves_','isSaved')
open(p,'w').write(s)
EOF
grep -n "^const\|^type\|^// The sheet" settings.ts

